/* FIXTURE : stand-in local de jQuery 1.8.3 (aucun code tiers). Expose $ et $(fn).ready pour le site daté. */
window.jQuery = window.$ = function (x) { var api = { ready: function (fn) { document.addEventListener("DOMContentLoaded", fn); return api }, css: function (k, v) { var el = typeof x === "string" ? document.querySelector(x) : null; if (el) el.style[k] = v; return api } }; if (typeof x === "function") document.addEventListener("DOMContentLoaded", x); return api };
